package com.truckload.controller;
import android.widget.*;
import android.text.*;
import java.util.*;
/** Persistent zone sizing; source of truth is the controller, never phone storage. */
final class StripSettings {
 private Disclosure section;private String savedSummary="Connect to read saved zones.";
 private final MainActivity a;private final EditText[] fields=new EditText[6],length=new EditText[2];private final TextView[] summary=new TextView[2];private final Button[] calculate=new Button[2];private Button save,refresh;private TextView status;private boolean ready,dirty,loading,pending;private long sentAt;private int[] max={240,120};
 StripSettings(MainActivity activity){a=activity;}
 private EditText input(LinearLayout p,String name,boolean decimal){p.addView(a.text(name,13,0xffedf3fa));EditText e=new EditText(a);e.setSingleLine(true);e.setTextColor(0xffedf3fa);e.setInputType(decimal?8194:2);p.addView(e);return e;}
 void build(LinearLayout parent){section=new Disclosure(a,parent,"Strip setup",savedSummary);LinearLayout p=section.body;p.addView(a.text("One group is one controllable section. Enter groups or calculate from meters using the strip label.",12,0xffa2b1c4));for(int z=0;z<2;z++){final int zone=z;p.addView(a.text("Zone "+(z+1),16,0xffedf3fa));fields[z]=input(p,"Addressable groups",false);fields[z+2]=input(p,"Physical LEDs per meter",false);fields[z+4]=input(p,"Physical LEDs per group",false);length[z]=input(p,"Strip length · meters",true);calculate[z]=a.button("Calculate groups from length",()->calculate(zone),false);a.addButton(p,calculate[z]);summary[z]=a.text("Read strip size from Heltec first.",12,0xffa2b1c4);p.addView(summary[z]);}status=a.text("Connect to firmware 0.6.4 to read saved strip sizes.",12,0xffa2b1c4);p.addView(status);save=a.button("Save both zones to Heltec",this::save,false);refresh=a.button("Read saved sizes / discard edits",()->{dirty=false;ready=false;a.send("GET_STRIP_CONFIG");update();},false);a.addButton(p,save);a.addButton(p,refresh);for(EditText e:fields)e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){if(!loading){dirty=true;status.setText("Changes have not been saved.");summaries();update();}}});update();}
 private int number(int i){String s=fields[i].getText().toString();if(!s.matches("[0-9]{1,5}"))return -1;try{return Integer.parseInt(s);}catch(Exception e){return -1;}}
 private boolean valid(){for(int z=0;z<2;z++)if(number(z)<1||number(z)>max[z]||number(z+2)<1||number(z+2)>1000||number(z+4)<1||number(z+4)>30)return false;return true;}
 private void summaries(){for(int z=0;z<2;z++){int n=number(z),d=number(z+2),g=number(z+4);summary[z].setText(n>0&&d>0&&g>0?String.format(Locale.US,"%d groups · %d physical LEDs · %.3f m (maximum %d groups)",n,n*g,n*g/(double)d,max[z]):"Enter complete strip settings.");}}
 private void calculate(int z){try{double m=Double.parseDouble(length[z].getText().toString()),raw=m*number(z+2)/number(z+4);long n=Math.round(raw);if(!Double.isFinite(raw)||m<=0||number(z+2)<1||number(z+4)<1||n<1||n>max[z])throw new Exception();fields[z].setText(Long.toString(n));status.setText("Calculated "+n+" whole groups. Review the represented length above, then save.");}catch(Exception e){a.notice("Check length, density and LEDs per group. The resulting count must fit this zone.");}}
 private void save(){if(!ready||!a.isConnected()||pending)return;if(!valid()){a.notice("Use whole numbers within the zone limits; density 1–1000, LEDs per group 1–30.");return;}StringBuilder cmd=new StringBuilder("SET_STRIP_CONFIG");for(int i=0;i<6;i++)cmd.append('|').append(number(i));pending=true;sentAt=android.os.SystemClock.elapsedRealtime();status.setText("Saving… waiting for Heltec confirmation.");update();a.send(cmd.toString());}
 void record(String line){String[] x=line.split("\\|",-1);if(x[0].equals("STRIP_CONFIG")&&x.length==9){try{int[] v=new int[8];for(int i=0;i<8;i++){v[i]=Integer.parseInt(x[i+1]);if(v[i]<1)throw new Exception();}savedSummary="Zone 1 · "+v[0]+" groups · "+(v[0]*v[4])+" LEDs\nZone 2 · "+v[1]+" groups · "+(v[1]*v[5])+" LEDs";ready=true;max[0]=v[6];max[1]=v[7];if(!dirty){loading=true;for(int i=0;i<6;i++)fields[i].setText(Integer.toString(v[i]));for(int z=0;z<2;z++)length[z].setText(String.format(Locale.US,"%.3f",v[z]*v[z+4]/(double)v[z+2]));loading=false;summaries();status.setText("Saved strip sizes read from Heltec.");}}catch(Exception e){loading=false;}}
 if(line.equals("OK|SET_STRIP_CONFIG")){pending=false;dirty=false;status.setText("Saved on Heltec. Settings survive power loss.");}
 if(line.startsWith("ERR|")&&pending){pending=false;status.setText("Save rejected. Check the settings; your edits are still here.");}update();}
 void disconnected(){ready=false;pending=false;update();}
 void update(){if(save==null)return;section.summary((!a.isConnected()&&savedSummary.startsWith("Zone")?"Last read · ":"")+savedSummary+(dirty?"\nUnsaved changes":"")+(pending?"\nSaving…":""));if(pending&&android.os.SystemClock.elapsedRealtime()-sentAt>6000){pending=false;status.setText("Save confirmation unavailable. Read saved sizes before retrying.");}boolean enabled=a.isConnected()&&ready&&!pending;for(EditText e:fields)e.setEnabled(enabled);for(EditText e:length)e.setEnabled(enabled);for(Button b:calculate)b.setEnabled(enabled);save.setEnabled(enabled);refresh.setEnabled(a.isConnected()&&!pending);}
}
